   @Component({
     selector: 'app-text-editor',
     templateUrl: './text-editor.component.html',
     styleUrls: ['./text-editor.component.css']
   })
   export class TextEditorComponent {
     text = '';

     onChange(text: string) {
       this.text = text;
     }
   }
   ```

4. **List Management Component:**
   This component manages the list of items and handles user selections.

   ```typescript
   // src/app/list-management.component.ts
   import { Component } from '@angular/core';
   import { ItemService } from '../item.service'; // Assuming you have an item service

   @Component({
     selector: 'app-list-management',
     templateUrl: './list-management.component.html',
     styleUrls: ['./list-management.component.css']
   })
